static CGPoint RunnerPointerPointAt(
  double x,
  double y,
  double dx,
  double dy,
  double scale,
  double degrees,
  double baseRadius,
  double t,
  double side
) {
  double centerX = x + dx * t;
  double centerY = y + dy * t;
  double startRadius = baseRadius / MAX(scale, 1.0);
  double endRadius = baseRadius;
  if (scale < 1.0) {
